pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        vm.assume(depositAmount > 0 && withdrawAmount > 0);
        vm.assume(depositAmount <= type(uint256).max / 2); // prevent overflow in tests
        vm.assume(withdrawAmount <= depositAmount);

        // Deposit funds
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.deposit{value: depositAmount}();

        // Get initial balance
        uint256 initialBalance = address(c).balance;
        uint256 initialCredit = c.credit(actor); // public mapping getter

        // Withdraw
        vm.prank(actor);
        bool ok = true;
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        // Only test successful withdrawal scenarios
        if (ok) {
            uint256 finalBalance = address(c).balance;
            // Rule: after a successful withdrawAll, contract balance must equal initialBalance - initialCredit
            assertTrue(finalBalance == initialBalance - initialCredit);
        }
    }
}

