import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, uint96 depositAmount, uint96 withdrawAmount) public {
        vm.assume(actor != address(0));
        vm.assume(depositAmount > 0 && withdrawAmount > 0 && depositAmount >= withdrawAmount);

        // Fund actor and make deposit
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.deposit{value: depositAmount}();

        // Record balance before withdrawal
        uint256 balanceBefore = address(c).balance;

        // Perform withdrawal
        vm.prank(actor);
        c.withdrawAll();

        uint256 balanceAfter = address(c).balance;
        uint256 expectedBalance = balanceBefore - withdrawAmount;

        // For the reference contract, after a single deposit and a single withdrawAll,
        // the balance must be exactly depositAmount - withdrawAmount (since all credit was taken).
        // The mutant deducts balance by 1 instead of withdrawAmount, so balanceAfter will differ.
        // More generally: after withdrawAll, the contract's ETH balance must equal the sum of all
        // remaining credits. Since actor's credit was fully withdrawn, total remaining credit is 0.
        // Thus: balanceAfter must be depositAmount - withdrawAmount.
        // The fuzzer explores depositAmount, withdrawAmount, and actor to find a mismatch.
        assertTrue(balanceAfter == expectedBalance);
    }
}

