pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 d1, uint256 d2) public {
        // ensure we have enough ether to deposit
        d1 = bound(d1, 1, address(this).balance / 10);
        d2 = bound(d2, 1, address(this).balance / 10);

        // deploy the reentrant attacker
        Attacker attacker = new Attacker(c);

        // deposit to the attacker and to this test contract
        vm.deal(address(attacker), d1);
        vm.prank(address(attacker));
        c.deposit{value: d1}();

        vm.deal(address(this), d2);
        c.deposit{value: d2}();

        // attacker triggers withdrawAll, which will re-enter and record the received ether
        bool success;
        vm.prank(address(attacker));
        try attacker.attack() {
            success = true;
        } catch {
            success = false;
        }

        // property: after a successful attack, the contract's ether balance must be 0
        // because the attacker drained all deposited funds through reentrancy.
        // The mutant never decreases `balance` but sends ether anyway,
        // so the invariant that a zero ether balance implies no recorded credits breaks.
        // Here we assert a precise rule: if the attack succeeded,
        // address(c).balance must be strictly less than the sum of recorded credits.
        // The reference satisfies this because it correctly decrements `balance`;
        // the mutant leaves `balance` unchanged, making address(c).balance < sum(credit) impossible.
        if (success) {
            uint256 sumCredits = attacker.received();
            assertTrue(address(c).balance < sumCredits);
        }
    }
}

