pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        depositAmount = bound(depositAmount, 1, type(uint128).max);
        withdrawAmount = bound(withdrawAmount, 1, depositAmount);

        // Deposit funds to establish credit
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.deposit{value: depositAmount}();

        // Deploy a reentrant attacker that calls withdrawAll again during the first withdrawal
        ReentrantAttacker attacker = new ReentrantAttacker(c);
        vm.deal(address(attacker), 0);
        // Attacker deposits some of its own to get credit
        vm.deal(address(attacker), depositAmount);
        vm.prank(address(attacker));
        c.deposit{value: depositAmount}();

        uint256 balanceBefore = address(c).balance;

        // Trigger the attack: attacker withdrawAll, reenters and withdrawAll again
        vm.prank(address(attacker));
        attacker.attack();

        uint256 balanceAfter = address(c).balance;
        // Rule: balance should never decrease by more than the total credit that was legitimately withdrawn.
        // Here attacker had credit == depositAmount. A correct contract would deduct exactly depositAmount once.
        // The bug allows double withdrawal, reducing balance by 2*depositAmount.
        assertTrue(balanceAfter >= balanceBefore - depositAmount);
    }
}

contract ReentrantAttacker {
    C public target;
    bool private attacking;
    constructor(C _target) { target = _target; }
    function attack() external payable {
        attacking = true;
        target.withdrawAll();
        attacking = false;
    }
    receive() external payable {
        if (attacking) {
            target.withdrawAll();
        }
    }
}

