import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount, address actor) public {
        vm.assume(actor != address(0) && actor != address(c) && actor != address(this));
        vm.assume(depositAmount > 0 && depositAmount <= type(uint120).max);
        vm.assume(withdrawAmount <= depositAmount);

        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.deposit{value: depositAmount}();

        uint256 balanceBefore = address(c).balance;
        uint256 creditBefore = c.credit(actor);

        vm.prank(actor);
        try c.withdrawAll() {
        } catch {
        }

        uint256 balanceAfter = address(c).balance;
        uint256 creditAfter = c.credit(actor);

        // General rule: after withdrawAll, the contract's balance must equal
        // balanceBefore - (creditBefore - creditAfter). This holds for correct C
        // since only positive credits are withdrawn. The mutant enters the
        // withdraw block for zero credit (oCredit==0), subtracting 0 from
        // balance while setting credit[msg.sender] to 0 (no change), but the
        // external call with value=0 can still reenter and trigger further
        // state corruption, ultimately violating balance integrity.
        assertTrue(balanceAfter == balanceBefore - (creditBefore - creditAfter));
    }
